    def test_required_calls(self):  # reward: 1.0
        tree = ast.parse(__solution_source__)
        required = ['random_cnotdihedral', 'to_circuit']
        import builtins as _builtins
        _alias_to_real = _builtins.dict()

        def _alias_map_is_falsy_const(_test):
            return _builtins.isinstance(_test, ast.Constant) and not _test.value

        def _alias_map_is_truthy_const(_test):
            return _builtins.isinstance(_test, ast.Constant) and _builtins.bool(_test.value)

        def _alias_map_const_int(_node):
            if _builtins.isinstance(
                _node, ast.Constant
            ) and _builtins.isinstance(_node.value, _builtins.int):
                return _node.value
            if _builtins.isinstance(_node, ast.UnaryOp) and _builtins.isinstance(
                _node.op, (ast.USub, ast.UAdd)
            ):
                _inner = _alias_map_const_int(_node.operand)
                if _inner is not None:
                    return -_inner if _builtins.isinstance(_node.op, ast.USub) else _inner
            return None

        def _alias_map_is_empty_iter(_it):
            if _builtins.isinstance(_it, (ast.List, ast.Tuple, ast.Set)) and not _it.elts:
                return True
            if _builtins.isinstance(_it, ast.Dict) and not _it.keys:
                return True
            if (
                _builtins.isinstance(_it, ast.Call)
                and _builtins.isinstance(_it.func, ast.Name)
                and _it.func.id in ('set', 'frozenset', 'list', 'tuple', 'dict')
                and not _it.args
                and not _it.keywords
            ):
                return True
            if (
                _builtins.isinstance(_it, ast.Call)
                and _builtins.isinstance(_it.func, ast.Name)
                and _it.func.id == 'range'
                and not _it.keywords
                and 1 <= _builtins.len(_it.args) <= 3
            ):
                _vals = [_alias_map_const_int(_a) for _a in _it.args]
                if _builtins.all(_v is not None for _v in _vals):
                    try:
                        return _builtins.len(_builtins.range(*_vals)) == 0
                    except (TypeError, ValueError):
                        return False
            return False

        def _alias_map_walk_live(_node, _dead):
            if _dead:
                return
            if _builtins.isinstance(
                _node,
                (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda, ast.ClassDef),
            ):
                return
            if _builtins.isinstance(_node, (ast.Import, ast.ImportFrom)):
                for _alias in _node.names:
                    if _alias.asname:
                        _alias_to_real[_alias.asname] = _alias.name
                return
            if _builtins.isinstance(_node, ast.If):
                if _alias_map_is_falsy_const(_node.test):
                    for _child in _node.body:
                        _alias_map_walk_live(_child, True)
                    for _child in _node.orelse:
                        _alias_map_walk_live(_child, False)
                    return
                if _alias_map_is_truthy_const(_node.test):
                    for _child in _node.body:
                        _alias_map_walk_live(_child, False)
                    for _child in _node.orelse:
                        _alias_map_walk_live(_child, True)
                    return
            if _builtins.isinstance(_node, ast.While):
                if _alias_map_is_falsy_const(_node.test):
                    for _child in _node.orelse:
                        _alias_map_walk_live(_child, False)
                    return
                if _alias_map_is_truthy_const(_node.test):
                    for _child in _node.body:
                        _alias_map_walk_live(_child, False)
                    for _child in _node.orelse:
                        _alias_map_walk_live(_child, True)
                    return
            if _builtins.isinstance(_node, ast.For) and _alias_map_is_empty_iter(_node.iter):
                for _child in _node.orelse:
                    _alias_map_walk_live(_child, False)
                return
            for _child in ast.iter_child_nodes(_node):
                _alias_map_walk_live(_child, False)

        _alias_map_walk_live(tree, False)
        called = _builtins.set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                if isinstance(node.func, ast.Name):
                    called.add(node.func.id)
                    called.add(_alias_to_real.get(node.func.id, node.func.id))
                elif isinstance(node.func, ast.Attribute):
                    called.add(node.func.attr)
        for name in required:
            self.assertIn(
                name, called,
                msg="Required API was not actually called: " + name,
            )

    def test_required_modules(self):  # reward: 1.0
        tree = ast.parse(__solution_source__)
        required = ['qiskit.quantum_info']
        import builtins as _builtins
        imports = _builtins.set()
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom) and node.module:
                imports.add(node.module)
            elif isinstance(node, ast.Import):
                for alias in node.names:
                    imports.add(alias.name)
