        def _module_scope_binds_name(
            stmts, name, before_line, in_loop=False, skip=None
        ):
            for n in stmts:
                if not in_loop and n.lineno >= before_line:
                    continue
                if _contains_namedexpr_binding(
                    n, name, before_line, in_loop, skip
                ):
                    return True
                if builtins.isinstance(n, ast.Assign):
                    for tgt in n.targets:
                        if _target_binds_name(tgt, name):
