                        return True
                elif builtins.isinstance(n, (ast.For, ast.AsyncFor)):
                    if _target_binds_name(n.target, name):
                        return True
                    if n is skip:
                        continue
                    if _module_scope_binds_name(
                        n.body, name, before_line, True, skip
                    ) or _module_scope_binds_name(
                        n.orelse, name, before_line, in_loop, skip
                    ):
                        return True
                elif builtins.isinstance(n, ast.While):
                    if n is skip:
                        continue
                    if _module_scope_binds_name(
                        n.body, name, before_line, True, skip
                    ) or _module_scope_binds_name(
                        n.orelse, name, before_line, in_loop, skip
                    ):
                        return True
