                    if _module_scope_binds_name(
                        n.orelse, name, before_line, in_loop, skip
                    ) or _module_scope_binds_name(
                        n.finalbody, name, before_line, in_loop, skip
                    ):
                        return True
                elif builtins.isinstance(n, ast.Match):
                    for case in n.cases:
