    def test_unitary_equiv_random_cnotdihedral(self):  # reward: 1.0
        from qiskit.circuit import QuantumCircuit
        from qiskit.quantum_info import Operator
        ref = QuantumCircuit(1)
        ref = dihedral
        self.assertTrue(
