    def test_ast_no_banned_imports(self):  # reward: -1.0
        tree = ast.parse(__solution_source__)
        banned = ['qiskit.opflow', 'qiskit.algorithms', 'qiskit.pulse', 'qiskit.extensions', 'qiskit.providers.basicaer', 'qiskit.qasm']
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom) and node.module:
                for b in banned:
                    self.assertFalse(
                        node.module == b or node.module.startswith(b + '.'),
                        msg="Banned import: " + node.module,
                    )
            if isinstance(node, ast.Import):
                for alias in node.names:
                    for b in banned:
                        self.assertFalse(
                            alias.name == b or alias.name.startswith(b + '.'),
                            msg="Banned import: " + alias.name,
                        )

    def test_ast_no_banned_names(self):  # reward: -1.0
        tree = ast.parse(__solution_source__)
        banned_names = ['execute', 'QuantumInstance', 'QubitConverter', 'BasicAer', 'IBMQ', 'cnot', 'toffoli', 'fredkin', 'mct']
        for node in ast.walk(tree):
            if isinstance(node, ast.Name) and node.id in banned_names:
                self.fail(msg="Banned name used: " + node.id)
            if isinstance(node, ast.Attribute) and node.attr in banned_names:
                self.fail(msg="Banned attribute used: " + node.attr)
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                for alias in node.names:
                    if alias.name in banned_names:
                        self.fail(msg="Banned import used: " + alias.name)

    def test_ast_correct_channel(self):  # reward: -1.0
        tree = ast.parse(__solution_source__)
