def _euler_reference_signature(basis, target):
    from qiskit.synthesis import OneQubitEulerDecomposer
    ref = OneQubitEulerDecomposer(basis=basis)(target)
    return [
        (
            instr.operation.name,
            tuple(round(float(p), 9) for p in instr.operation.params),
        )
        for instr in ref.data
    ]


