import functools
import itertools
@functools.lru_cache(maxsize=None)
def _optmapper_ref_problem_hamiltonian():
    linear = {'x0': 0, 'x1': 3, 'x2': 2, 'x3': 2}
    quadratic = {('x0', 'x1'): 3, ('x2', 'x3'): 1}
    cubic = {('x0', 'x1', 'x2'): -1, ('x1', 'x2', 'x3'): 3}
    n = 4
    best = None
    for bits in itertools.product((0, 1), repeat=n):
        d = {f'x{i}': bits[i] for i in range(n)}
        val = 0.0
        for k, c in linear.items():
            val += c * d[k]
        for (a, b), c in quadratic.items():
            val += c * d[a] * d[b]
        for (a, b, cc), c in cubic.items():
            val += c * d[a] * d[b] * d[cc]
        if best is None or val < best:
            best = val
    from qiskit_addon_opt_mapper import OptimizationProblem
    from qiskit_addon_opt_mapper.converters import OptimizationProblemToHubo
    p = OptimizationProblem()
    for i in range(n):
        p.binary_var(f'x{i}')
    p.minimize(linear=linear, quadratic=quadratic, higher_order={3: cubic})
    ref_op, _ = OptimizationProblemToHubo().convert(p).to_ising()
    return ref_op.num_qubits, float(best), ref_op


